{"actions":[{"type":"raw_bash","command":"cd /app && (qemu-system-x86_64 -m 512 -nographic -serial telnet:127.0.0.1:6665,server,nowait -cdrom /app/alpine.iso -boot d -net none > /tmp/alpine-qemu.log 2>&1 & echo $! > /tmp/alpine-qemu.pid) && sleep 2 && python3 - <<'PY'
import socket,sys,time
host,port='127.0.0.1',6665
end=time.time()+30
buf=b''
while time.time()<end:
    try:
        s=socket.create_connection((host,port),timeout=2)
        s.settimeout(2)
        try:
            data=s.recv(4096)
            buf+=data
            if b'login' in buf.lower():
                print(buf.decode('utf-8','replace'))
                sys.exit(0)
        finally:
            s.close()
    except Exception:
        time.sleep(1)
print(buf.decode('utf-8','replace'))
sys.exit(1)
